// Regenerates src/lib/sami/knowledge.ts from the files in /knowledge.
// Run after editing the instructions or files 01-04:  npm run knowledge
import { readFileSync, writeFileSync } from "node:fs";

const files = [
  ["SAMI_INSTRUCTIONS", "00_Sami_Instructions.txt"],
  ["FAQ_01", "01_SPC_Member_Support_FAQ.md"],
  ["CONTENT_MAP_02", "02_SPC_Content_Map.md"],
  ["CORE_CONCEPTS_03", "03_SPC_Core_Concepts.md"],
  ["SITUATION_GUIDE_04", "04_SPC_Situation_Guide.md"],
];

const out = [
  "// GENERATED by scripts/build-knowledge.mjs from /knowledge. Do not edit by hand: edit the .md files and run `npm run knowledge`.",
  "",
];
for (const [name, file] of files) {
  const text = readFileSync(new URL(`../knowledge/${file}`, import.meta.url), "utf8").trim();
  out.push(`export const ${name} = ${JSON.stringify(text)};\n`);
}
writeFileSync(new URL("../src/lib/sami/knowledge.ts", import.meta.url), out.join("\n"));
console.log("knowledge.ts updated");
